def f(n):
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * factorial(n-1)

    result = []
    for i in range(1, n+1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            sum = 0
            for j in range(1, i+1):
                sum += j
            result.append(sum)
    return result

# Test 1
assert f(5) == [1, 2, 6, 24, 15]

# Test 2
assert f(1) == [1]

# Test 3
assert f(2) == [1, 1]

# Test 4
assert f(3) == [1, 2, 3]

# Test 5
assert f(6) == [1, 2, 6, 24, 15, 21]
```

